import json
n=30
g=[[0]*n for _ in range(n)]
# The frame occupies rows/columns 1..25. Add nested 5 outlines and 2-color separator rings through the 5x5 outline.
for r in range(1,26):
    for c in range(1,26):
        d=min(r-1,c-1,25-r,25-c)
        if d<=10:
            g[r][c]=5 if d%2==0 else 2
print(json.dumps(g, separators=(',',':')))

